    fun t(key: String, locale: String): String {
        val normalized = locale.replace('_', '-')
        val table = tables[normalized] ?: tables[normalized.substringBefore('-')] ?: tables.getValue("en-GB")
        return table[key] ?: tables.getValue("en-GB")[key] ?: key
    }
